/*
 * mx-charts.js: every chart on the Matristics Home and Benchmark pages.
 *
 * DATA
 *   Reads window.MATRISTICS, generated by _dev/build_benchmark_data.py into
 *   benchmark/benchmark-data.js. This file holds no scores of its own, so
 *   re-running the build script updates every chart.
 *
 * HOW IT IS ORGANISED
 *   1. Helpers: data access, colours (read live from CSS variables so both
 *      dark and light mode work), small DOM and number helpers.
 *   2. Radar engine: draws a radar as SVG, then animates it. First draw:
 *      the shape grows out of the centre (CSS, see theme.scss section 12).
 *      Later changes (another model, another figure): the points glide to
 *      their new positions (requestAnimationFrame tween below).
 *   3. One "mount" function per chart. A mount looks for its container by
 *      id and does nothing if the page does not have it, so the same file
 *      serves both pages:
 *        #mx-hero        Home: radar with model buttons
 *        #mx-board       Home + Benchmark: leaderboard
 *        #mx-find-dims, #mx-find-premise, #mx-find-figs   Home: findings
 *        #mx-explorer    Benchmark: figure filter, model and compare
 *                        buttons, big radar and the model's score card
 *        #mx-heat        Benchmark: model x question heatmap
 *        #mx-dumb        Benchmark: Macrina vs Olympias per dimension
 *        #mx-tags        Benchmark: error tag counts
 *   4. Boot: mount everything, and redraw in the new colours when the
 *      reader toggles dark/light (the "mx:theme" event from site.html).
 *
 * ANIMATION AND ACCESSIBILITY
 *   Bars, dots, cells and dumbbells are plain HTML; their entrance
 *   animations are pure CSS keyed off .mx-reveal / .is-in. Everything is
 *   switched off by the reduce-motion setting. Buttons are real <button>s
 *   with aria-pressed; each chart has an aria-label or a text alternative.
 */
(function () {
  "use strict";

  var D = window.MATRISTICS;
  if (!D) { console.warn("mx-charts: benchmark-data.js did not load"); return; }

  // =====================================================================
  // 1. Helpers
  // =====================================================================

  var DIMS = [
    { key: "HA", name: "Historical accuracy" },
    { key: "COV", name: "Coverage" },
    { key: "FA", name: "Framing & agency" },
    { key: "EQ", name: "Epistemic quality" }
  ];
  var Q = D.questions;                       // in order M1..M18, O1..O17
  var N = Q.length;
  var RANKED = D.models.slice().sort(function (a, b) { return b.overall - a.overall; });
  var byKey = function (k) { return D.models.filter(function (m) { return m.key === k; })[0]; };
  var rankOf = function (m) { return RANKED.indexOf(m) + 1; };

  // Two decimals, rounding half up (4.725 -> 4.73; plain toFixed gives 4.72
  // because 4.725 is stored as 4.72499...).
  var f2 = function (x) { return (x + 1e-9).toFixed(2); };

  // Read a colour token from the active stylesheet (see theme.scss, section 2).
  function tok(name) { return getComputedStyle(document.documentElement).getPropertyValue("--mx-" + name).trim(); }

  var motionOff = function () {
    var m = document.documentElement.getAttribute("data-mx-motion");
    var os = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    return m === "off" || (m !== "on" && os);
  };

  // Escape text before putting it in innerHTML (question texts, names).
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }

  // Percentage of the way from lo to hi, clamped to 0..100.
  function pct(v, lo, hi) { return Math.max(0, Math.min(1, (v - lo) / (hi - lo))) * 100; }

  // A bar: the fill width goes in --w so CSS can animate it from zero.
  function bar(width, cls, i) {
    return '<span class="mx-bar ' + (cls || "") + '" style="--i:' + (i || 0) + '"><span style="--w:' + width.toFixed(1) + '%"></span></span>';
  }

  // A row of buttons that behave as a single-choice group. `items` are
  // {value, label}; onPick(value) is called on click.
  function pills(el, items, current, onPick, extraClass) {
    el.innerHTML = items.map(function (it) {
      return '<button type="button" class="mx-pill ' + (extraClass || "") + '" data-v="' + esc(it.value) + '" aria-pressed="' + (it.value === current) + '">' + esc(it.label) + "</button>";
    }).join("");
    el.onclick = function (e) {
      var b = e.target.closest("button");
      if (b) onPick(b.getAttribute("data-v"));
    };
  }

  // Interpolate the heatmap ramp (three stops from the theme) for value v
  // on the 3.0..5.0 scale.
  function heatColor(v) {
    var stops = [tok("heat-0"), tok("heat-1"), tok("heat-2")].map(hexToRgb);
    var t = (pct(v, 3, 5) / 100) * 2, i = Math.min(1, Math.floor(t)), f = t - i;
    var c = stops[i].map(function (x, k) { return Math.round(x + (stops[i + 1][k] - x) * f); });
    return "rgb(" + c.join(",") + ")";
  }
  function hexToRgb(h) {
    h = h.replace("#", "");
    if (h.length === 3) h = h.split("").map(function (c) { return c + c; }).join("");
    var n = parseInt(h, 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }

  // Shared floating tooltip (heatmap cells).
  var tipEl;
  function tip(evt, html) {
    if (!tipEl) { tipEl = document.createElement("div"); tipEl.className = "mx-tip"; tipEl.setAttribute("role", "tooltip"); document.body.appendChild(tipEl); }
    tipEl.innerHTML = html;
    tipEl.style.display = "block";
    var r = tipEl.getBoundingClientRect(), x = evt.clientX + 14, y = evt.clientY + 14;
    if (x + r.width > innerWidth - 8) x = evt.clientX - r.width - 14;
    if (y + r.height > innerHeight - 8) y = evt.clientY - r.height - 14;
    tipEl.style.left = x + "px"; tipEl.style.top = y + "px";
  }
  function untip() { if (tipEl) tipEl.style.display = "none"; }

  // =====================================================================
  // 2. Radar engine
  //
  // Geometry: SVG viewBox 400x400, centre (200,200). The outer ring
  // (radius 160) is score 5; the centre is score `lo` (3 by default, so
  // the small differences between models are visible; the axis is stated
  // in every caption). Spoke 0 is at the top and spokes go clockwise.
  // =====================================================================

  function Radar(host, opts) {
    this.host = host;
    this.lo = opts.lo || 3;
    this.ids = [];           // question ids currently on the spokes
    this.kinds = "";         // layer kinds currently drawn, e.g. "field,primary"
    this.values = [];        // current values per layer, for tweening
    this.labelSize = opts.labelSize || "";
    host.classList.add("mx-radar");
    host.setAttribute("role", "img");
  }

  // Point for spoke i of n at value v, as [x, y].
  Radar.prototype.pt = function (i, n, v) {
    var a = -Math.PI / 2 + (2 * Math.PI * i) / n;
    var r = 160 * Math.max(0, (v - this.lo) / (5 - this.lo));
    return [200 + r * Math.cos(a), 200 + r * Math.sin(a)];
  };
  Radar.prototype.points = function (vals) {
    var self = this, n = vals.length;
    return vals.map(function (v, i) { var p = self.pt(i, n, v); return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" ");
  };

  // Arc just outside the rings covering spokes from..to: marks which
  // figure a run of questions belongs to.
  Radar.prototype.arc = function (from, to, n) {
    var R = 173, a0 = -Math.PI / 2 + (2 * Math.PI * (from - 0.4)) / n, a1 = -Math.PI / 2 + (2 * Math.PI * (to + 0.4)) / n;
    return "M" + (200 + R * Math.cos(a0)).toFixed(1) + " " + (200 + R * Math.sin(a0)).toFixed(1) +
      "A" + R + " " + R + " 0 " + (a1 - a0 > Math.PI ? 1 : 0) + " 1 " + (200 + R * Math.cos(a1)).toFixed(1) + " " + (200 + R * Math.sin(a1)).toFixed(1);
  };

  // Full (re)draw. `layers` is a list of {name, values, kind} where kind is
  // "field" (dashed average), "compare" or "primary"; drawn in that order.
  // `ids` are the question ids for the spokes.
  Radar.prototype.draw = function (ids, layers, label) {
    var self = this, n = ids.length;
    var line = tok("line"), line2 = tok("line-2");
    var spokes = "";
    for (var i = 0; i < n; i++) { var p = this.pt(i, n, 5); spokes += "M200 200L" + p[0].toFixed(1) + " " + p[1].toFixed(1); }

    // Figure arcs, only when the spokes include both figures' questions.
    var arcs = "";
    ["M", "O"].forEach(function (fig) {
      var idx = ids.map(function (id, i) { return id[0] === fig ? i : -1; }).filter(function (i) { return i >= 0; });
      if (idx.length && idx.length < n) {
        arcs += '<path d="' + self.arc(idx[0], idx[idx.length - 1], n) + '" fill="none" stroke="' + (fig === "M" ? tok("gold") : tok("olympias")) + '" stroke-width="4" stroke-linecap="round" opacity="0.8"/>';
      }
    });

    var ticks = [3.5, 4, 4.5, 5].filter(function (v) { return v > self.lo; }).map(function (v) {
      var y = 200 - 160 * (v - self.lo) / (5 - self.lo);
      return '<text x="204" y="' + (y - 3).toFixed(1) + '" fill="' + tok("faint") + '" font-size="8">' + v.toFixed(1) + "</text>";
    }).join("");
    var rings = [0.25, 0.5, 0.75, 1].map(function (f, k) {
      return '<circle cx="200" cy="200" r="' + 160 * f + '" fill="none" stroke="' + (k === 3 ? line2 : line) + '"/>';
    }).join("");

    var polys = layers.map(function (L) {
      var color = L.kind === "field" ? tok("faint") : L.kind === "compare" ? tok("compare") : tok("series");
      var fill = L.kind === "field" ? "none" : L.kind === "compare" ? hexAlpha(tok("compare"), 0.12) : tok("series-fill");
      var dash = L.kind === "field" ? ' stroke-dasharray="4 4"' : "";
      var w = L.kind === "field" ? 1.5 : 2.2;
      return '<polygon class="mx-poly" data-name="' + esc(L.name) + '" points="' + self.points(L.values) + '" fill="' + fill + '" stroke="' + color + '" stroke-width="' + w + '" stroke-linejoin="round"' + dash + "/>";
    }).join("");

    var labels = ids.map(function (id, i) {
      var a = -Math.PI / 2 + (2 * Math.PI * i) / n;
      var flag = (Q.filter(function (q) { return q.id === id; })[0] || {}).flagged;
      return '<span class="mx-radar-lbl' + (flag ? " is-flag" : "") + '" style="left:' + (50 + 47.5 * Math.cos(a)).toFixed(2) + "%;top:" + (50 + 47.5 * Math.sin(a)).toFixed(2) + "%" + (self.labelSize ? ";font-size:" + self.labelSize : "") + '">' + id + "</span>";
    }).join("");

    this.host.innerHTML = '<svg viewBox="0 0 400 400" aria-hidden="true">' + rings +
      '<path d="' + spokes + '" stroke="' + line + '" stroke-width="1" opacity="0.8"/>' + ticks + arcs + polys + "</svg>" + labels;
    this.host.setAttribute("aria-label", label);
    this.ids = ids.slice();
    this.kinds = layers.map(function (L) { return L.kind; }).join();
    this.values = layers.map(function (L) { return L.values.slice(); });
    this.reveal();
  };

  // Same spokes, new values: glide each polygon to its new shape. Layers are
  // matched by position and kind (field / compare / primary), not by name,
  // so switching models tweens the primary shape. Falls back to a redraw
  // when the spokes changed (figure filter), a layer was added or removed
  // (compare switched on or off), or motion is off.
  Radar.prototype.update = function (ids, layers, label) {
    var self = this;
    var kinds = layers.map(function (L) { return L.kind; }).join();
    if (ids.join() !== this.ids.join() || kinds !== this.kinds || motionOff()) {
      this.draw(ids, layers, label);
      this.host.classList.add("is-drawn");
      return;
    }
    var polys = this.host.querySelectorAll(".mx-poly");
    var from = this.values;
    var t0 = null, dur = 520;
    function frame(t) {
      if (t0 === null) t0 = t;
      var p = Math.min(1, (t - t0) / dur), e = 1 - Math.pow(1 - p, 3);   // ease-out cubic
      layers.forEach(function (L, j) {
        var vals = L.values.map(function (v, i) { return from[j][i] + (v - from[j][i]) * e; });
        polys[j].setAttribute("points", self.points(vals));
      });
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
    layers.forEach(function (L, j) { polys[j].setAttribute("data-name", L.name); });
    this.values = layers.map(function (L) { return L.values.slice(); });
    this.host.setAttribute("aria-label", label);
  };

  // First appearance: grow from the centre once the radar is on screen.
  Radar.prototype.reveal = function () {
    var host = this.host;
    if (host.classList.contains("is-drawn")) return;
    if (!("IntersectionObserver" in window) || motionOff()) { host.classList.add("is-drawn"); return; }
    var io = new IntersectionObserver(function (es) {
      if (es[0].isIntersecting) { requestAnimationFrame(function () { host.classList.add("is-drawn"); }); io.disconnect(); }
    }, { threshold: 0.25 });
    io.observe(host);
  };

  function hexAlpha(hex, a) { var c = hexToRgb(hex); return "rgba(" + c.join(",") + "," + a + ")"; }

  // =====================================================================
  // 3. Charts
  // =====================================================================

  var ids = Q.map(function (q) { return q.id; });
  var fieldVals = Q.map(function (q) { return q.mean; });
  var valsOf = function (m, which) { return which.map(function (id) { return m.perQuestion[id]; }); };

  // ---- Home: radar with model buttons --------------------------------
  function mountHero() {
    var root = document.getElementById("mx-hero");
    if (!root) return;
    var state = { sel: RANKED[0].key };
    root.innerHTML =
      '<div class="mx-panel-head"><h2 class="mx-h2" style="font-size:1.3rem;font-family:inherit;font-weight:700">Performance profile</h2>' +
      '<span class="mx-sub">one spoke per question · axis 3 to 5</span></div>' +
      '<div class="mx-pills" data-role="pills"></div>' +
      '<div data-role="radar"></div>' +
      '<div class="mx-key" data-role="key" style="justify-content:center;margin-top:.4rem"></div>';
    var radar = new Radar(root.querySelector('[data-role="radar"]'), { labelSize: "0.55rem" });
    function render(first) {
      var m = byKey(state.sel);
      pills(root.querySelector('[data-role="pills"]'), D.models.map(function (x) { return { value: x.key, label: x.name }; }), state.sel,
        function (v) { state.sel = v; render(false); });
      var layers = [
        { name: "Average of all models", values: fieldVals, kind: "field" },
        { name: m.name, values: valsOf(m, ids), kind: "primary" }
      ];
      var label = "Radar of " + m.name + "'s mean score on each of 35 questions, with the all-model average.";
      if (first) radar.draw(ids, layers, label); else radar.update(ids, layers, label);
      root.querySelector('[data-role="key"]').innerHTML =
        '<span><i class="k-line" style="border-color:' + tok("series") + '"></i>' + esc(m.name) + " · " + f2(m.overall) + "</span>" +
        '<span><i class="k-dash" style="border-color:' + tok("faint") + '"></i>All-model average</span>' +
        '<span><i class="k-band" style="background:' + tok("gold") + '"></i>Macrina</span>' +
        '<span><i class="k-band" style="background:' + tok("olympias") + '"></i>Olympias</span>';
    }
    render(true);
    root._redraw = function () { render(true); };
  }

  // ---- Leaderboard ----------------------------------------------------
  function mountBoard() {
    var root = document.getElementById("mx-board");
    if (!root) return;
    root.innerHTML = '<ol class="mx-board">' + RANKED.map(function (m, i) {
      return '<li class="mx-row"><span class="mx-rank">' + (i + 1) + "</span>" +
        '<span class="mx-id"><span class="mx-name">' + esc(m.name) + '</span><span class="mx-prov">' + esc(m.provider) + "</span></span>" +
        bar(pct(m.overall, 4, 5), "is-accent", i) +
        '<span class="mx-score">' + f2(m.overall) + "</span></li>";
    }).join("") + "</ol>";
  }

  // ---- Home findings ---------------------------------------------------
  function mountFindings() {
    var dims = document.getElementById("mx-find-dims");
    if (dims) {
      var weakest = DIMS.reduce(function (a, d) { return D.field.dims[d.key] < D.field.dims[a.key] ? d : a; });
      dims.innerHTML = DIMS.map(function (d, i) {
        var v = D.field.dims[d.key];
        return '<div class="mx-mini-row"><span>' + d.name + "</span>" + bar(pct(v, 4, 5), d === weakest ? "is-thin" : "is-thin is-quiet", i) + "<span>" + f2(v) + "</span></div>";
      }).join("");
    }
    var prem = document.getElementById("mx-find-premise");
    if (prem) {
      prem.innerHTML = D.models.slice().sort(function (a, b) { return b.premise.corrected - a.premise.corrected; }).map(function (m, r) {
        var dots = "";
        for (var k = 0; k < m.premise.of; k++) dots += '<span class="mx-dot' + (k < m.premise.corrected ? " is-on" : "") + '" style="--i:' + (r * 10 + k) + '"></span>';
        return '<div class="mx-mini-row no-val"><span>' + esc(m.name) + '</span><span class="mx-dots" role="img" aria-label="' + m.premise.corrected + " of " + m.premise.of + ' corrected">' + dots + "</span></div>";
      }).join("");
    }
    var figs = document.getElementById("mx-find-figs");
    if (figs) {
      // Shared axis 4.4..4.9 so every model's two figure means fit.
      var at = function (v) { return pct(v, 4.4, 4.9).toFixed(1) + "%"; };
      figs.innerHTML = RANKED.map(function (m, i) {
        var a = m.figures.M, b = m.figures.O;
        return '<div class="mx-mini-row no-val"><span>' + esc(m.name) + '</span><span class="mx-dumb" role="img" aria-label="Macrina ' + f2(a) + ", Olympias " + f2(b) + '" style="--i:' + i + '">' +
          '<span class="mx-dumb-line" style="left:' + at(Math.min(a, b)) + ";width:" + (pct(Math.max(a, b), 4.4, 4.9) - pct(Math.min(a, b), 4.4, 4.9)).toFixed(1) + '%"></span>' +
          '<span class="mx-dumb-m" style="left:' + at(a) + '"></span><span class="mx-dumb-o" style="left:' + at(b) + '"></span></span></div>';
      }).join("");
    }
  }

  // ---- Benchmark: the explorer (filter + buttons + radar + score card) ---
  var explorer = { sel: RANKED[0].key, cmp: "", fig: "all" };
  var explorerListeners = [];   // other charts that follow the selected model

  function mountExplorer() {
    var root = document.getElementById("mx-explorer");
    if (!root) return;
    root.innerHTML =
      '<div class="mx-split">' +
      '<div class="mx-main mx-panel">' +
      '<div class="mx-pills" style="margin-bottom:.5rem"><span class="mx-pills-label">Model</span><span class="mx-pills" data-role="sel"></span></div>' +
      '<div class="mx-pills"><span class="mx-pills-label">Compare</span><span class="mx-pills" data-role="cmp"></span></div>' +
      '<div data-role="radar"></div>' +
      '<div class="mx-key" data-role="key" style="justify-content:center"></div>' +
      "</div>" +
      '<div class="mx-side">' +
      '<div class="mx-panel" data-role="card" aria-live="polite"></div>' +
      '<div class="mx-panel mx-facts" data-role="facts"></div>' +
      "</div></div>";
    var radar = new Radar(root.querySelector('[data-role="radar"]'), {});
    var figSeg = document.getElementById("mx-figfilter");

    function render(first) {
      var st = explorer, m = byKey(st.sel), c = st.cmp ? byKey(st.cmp) : null;
      var shown = ids.filter(function (id) { return st.fig === "all" || id[0] === st.fig; });

      if (figSeg) pills(figSeg, [{ value: "all", label: "All questions" }, { value: "M", label: "Macrina" }, { value: "O", label: "Olympias" }], st.fig,
        function (v) { st.fig = v; render(false); });
      pills(root.querySelector('[data-role="sel"]'), D.models.map(function (x) { return { value: x.key, label: x.name }; }), st.sel,
        function (v) { st.sel = v; if (st.cmp === v) st.cmp = ""; render(false); });
      pills(root.querySelector('[data-role="cmp"]'), [{ value: "", label: "None" }].concat(D.models.filter(function (x) { return x.key !== st.sel; }).map(function (x) { return { value: x.key, label: x.name }; })), st.cmp,
        function (v) { st.cmp = v; render(false); }, "is-compare");

      var fieldShown = shown.map(function (id) { return Q.filter(function (q) { return q.id === id; })[0].mean; });
      var layers = [{ name: "Average of all models", values: fieldShown, kind: "field" }];
      if (c) layers.push({ name: c.name, values: valsOf(c, shown), kind: "compare" });
      layers.push({ name: m.name, values: valsOf(m, shown), kind: "primary" });
      var label = "Radar of mean score per question for " + m.name + (c ? " compared with " + c.name : "") + ", " + shown.length + " questions.";
      if (first) radar.draw(shown, layers, label); else radar.update(shown, layers, label);

      root.querySelector('[data-role="key"]').innerHTML =
        '<span><i class="k-line" style="border-color:' + tok("series") + '"></i>' + esc(m.name) + "</span>" +
        (c ? '<span><i class="k-line" style="border-color:' + tok("compare") + '"></i>' + esc(c.name) + "</span>" : "") +
        '<span><i class="k-dash" style="border-color:' + tok("faint") + '"></i>All-model average</span>';

      // Score card for the selected model.
      var low = shown.slice().sort(function (a, b) { return m.perQuestion[a] - m.perQuestion[b]; })[0];
      root.querySelector('[data-role="card"]').innerHTML =
        '<div class="mx-sub" style="margin:0">' + esc(m.provider) + " · rank " + rankOf(m) + " of " + D.models.length + "</div>" +
        '<div class="mx-model-name">' + esc(m.name) + "</div>" +
        '<div class="mx-bignum">' + f2(m.overall) + '</div><div class="mx-note" style="margin:.2rem 0 1rem">overall, on a 1 to 5 scale</div>' +
        '<div class="mx-mini mx-reveal is-in">' + DIMS.map(function (d, i) {
          return '<div class="mx-mini-row"><span>' + d.name + "</span>" + bar(pct(m.dims[d.key], 4, 5), "is-thin", i) + "<span>" + f2(m.dims[d.key]) + "</span></div>";
        }).join("") + "</div>";
      root.querySelector('[data-role="facts"]').innerHTML =
        '<div><div class="mx-fact-l">False premises corrected</div><div class="mx-fact-v">' + m.premise.corrected + "<small> / " + m.premise.of + "</small></div></div>" +
        '<div><div class="mx-fact-l">Lowest question shown</div><div class="mx-fact-v">' + low + " <small>" + f2(m.perQuestion[low]) + "</small></div></div>";

      explorerListeners.forEach(function (fn) { fn(); });
    }
    render(true);
    root._redraw = function () { render(true); };
  }

  // ---- Benchmark: heatmap ----------------------------------------------
  function mountHeat() {
    var root = document.getElementById("mx-heat");
    if (!root) return;
    var head = '<div class="mx-heat-row is-head" aria-hidden="true"><span></span>' + Q.map(function (q) {
      return '<span class="' + (q.flagged ? "is-flag" : "") + '">' + q.id + "</span>";
    }).join("") + "</div>";
    var k = 0;
    var rows = RANKED.map(function (m) {
      return '<div class="mx-heat-row"><span class="mx-heat-name">' + esc(m.name) + "</span>" + Q.map(function (q) {
        var v = m.perQuestion[q.id];
        return '<button type="button" class="mx-cell" style="--i:' + (k++) + ";background:" + heatColor(v) + '" data-m="' + m.key + '" data-q="' + q.id +
          '" aria-label="' + esc(m.name) + ", " + q.id + ": " + f2(v) + '"></button>';
      }).join("") + "</div>";
    }).join("");
    root.innerHTML = '<div class="mx-heat-scroll"><div class="mx-heat">' + head + rows + "</div></div>";
    var show = function (e) {
      var b = e.target.closest(".mx-cell"); if (!b) return;
      var m = byKey(b.getAttribute("data-m")), q = Q.filter(function (x) { return x.id === b.getAttribute("data-q"); })[0];
      var src = e.type === "focusin" ? (function () { var r = b.getBoundingClientRect(); return { clientX: r.right, clientY: r.bottom }; })() : e;
      tip(src, "<b>" + esc(m.name) + " · " + q.id + '</b><br><span class="q">' + esc(q.text) + "</span><br>Score <b>" + f2(m.perQuestion[q.id]) + "</b> · average " + f2(q.mean));
    };
    root.addEventListener("mousemove", show);
    root.addEventListener("focusin", show);
    root.addEventListener("mouseleave", untip);
    root.addEventListener("focusout", untip);
    root._redraw = mountHeat;
  }

  // ---- Benchmark: Macrina vs Olympias for the selected model -----------
  function mountDumb() {
    var root = document.getElementById("mx-dumb");
    if (!root) return;
    function render() {
      var m = byKey(explorer.sel);
      var at = function (v) { return pct(v, 4, 5).toFixed(1) + "%"; };
      var title = document.getElementById("mx-dumb-model");
      if (title) title.textContent = m.name;
      root.innerHTML = '<div class="mx-mini">' + DIMS.map(function (d, i) {
        var a = m.dimFig[d.key + "-M"], b = m.dimFig[d.key + "-O"];
        return '<div class="mx-mini-row"><span>' + d.name + '</span><span class="mx-dumb" role="img" aria-label="Macrina ' + f2(a) + ", Olympias " + f2(b) + '" style="--i:' + i + '">' +
          '<span class="mx-dumb-line" style="left:' + at(Math.min(a, b)) + ";width:" + (pct(Math.max(a, b), 4, 5) - pct(Math.min(a, b), 4, 5)).toFixed(1) + '%"></span>' +
          '<span class="mx-dumb-m" style="left:' + at(a) + '"></span><span class="mx-dumb-o" style="left:' + at(b) + '"></span></span>' +
          "<span>" + ((b - a) >= 0 ? "+" : "−") + Math.abs(b - a).toFixed(2) + "</span></div>";
      }).join("") + "</div>";
    }
    render();
    explorerListeners.push(render);
    root._redraw = render;
  }

  // ---- Benchmark: error tags (summed over all models) -------------------
  function mountTags() {
    var root = document.getElementById("mx-tags");
    if (!root) return;
    var totals = {};
    D.models.forEach(function (m) { Object.keys(m.tags).forEach(function (t) { totals[t] = (totals[t] || 0) + m.tags[t]; }); });
    // Evasion is a response-level tag (stored separately in the data), but
    // it is a failure mode, so it belongs in this chart.
    var evasion = D.models.reduce(function (n, m) { return n + ((m.responseTags || {}).evasion || 0); }, 0);
    var list = Object.keys(totals).map(function (t) { return [t, totals[t]]; });
    list.push(["evasion", evasion]);
    list.sort(function (a, b) { return b[1] - a[1]; });
    var max = list[0][1];
    root.innerHTML = '<div class="mx-mini">' + list.map(function (t, i) {
      var name = t[0].replace(/-/g, " ");
      return '<div class="mx-mini-row"><span>' + name.charAt(0).toUpperCase() + name.slice(1) + "</span>" + bar(pct(t[1], 0, max), "", i) + "<span>" + t[1] + "</span></div>";
    }).join("") + "</div>";
  }

  // =====================================================================
  // 4. Boot
  // =====================================================================
  function boot() {
    mountHero(); mountBoard(); mountFindings(); mountExplorer(); mountHeat(); mountDumb(); mountTags();
    // Dark/light toggled: redraw the charts whose colours are baked into
    // SVG attributes. (HTML bars and dots follow CSS by themselves.)
    window.addEventListener("mx:theme", function () {
      ["mx-hero", "mx-explorer", "mx-heat"].forEach(function (id) {
        var el = document.getElementById(id);
        if (el && el._redraw) el._redraw();
      });
      document.querySelectorAll(".mx-radar").forEach(function (r) { r.classList.add("is-drawn"); });
    });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot); else boot();
})();
